// Signs the release APKs with the key in keys/ (not versioned) and writes them to dist/<version>/ (not versioned).
//
//   node app/scripts/sign-release.js        (after ./gradlew assembleRelease; build-release.js does both)
//
// The Expo build signs the release with the debug key: this script aligns and signs every APK of
// app/android/app/build/outputs/apk/release again with zipalign + apksigner from the Android SDK build-tools,
// without touching android/ (generated by prebuild). With ABI splits the names become
// tinkerblink-<version>-<abi>.apk and tinkerblink-<version>-universal.apk, otherwise tinkerblink-<version>.apk.
// The APKs of the same version made earlier are replaced; SHA256SUMS.txt lists the checksums, for the release notes.
// The password is read from keys/keystore.properties and is never printed.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync, execSync } = require('child_process');

/**
 * Runs a program. On Windows .bat/.cmd files (apksigner.bat, gradlew.bat, npx) need cmd.exe: the command line is
 * built here, quoting the arguments with spaces or cmd characters (execFileSync with shell: true is deprecated).
 */
function exec(file, args, opts = {}) {
  if (process.platform !== 'win32') return execFileSync(file, args, opts);
  const quote = (a) => (/[\s"&|<>^%()]/.test(a) ? `"${a}"` : a);
  return execSync([file, ...args].map(quote).join(' '), opts);
}

const root = path.resolve(__dirname, '..', '..');
const keysDir = path.join(root, 'keys');
const propsFile = path.join(keysDir, 'keystore.properties');
const apkDir = path.join(root, 'app', 'android', 'app', 'build', 'outputs', 'apk', 'release');
const distDir = path.join(root, 'dist');

/** version and versionCode from app/app.json. */
function appVersions() {
  const expo = JSON.parse(fs.readFileSync(path.join(root, 'app', 'app.json'), 'utf8')).expo;
  return { version: expo.version, versionCode: expo.android?.versionCode ?? 1 };
}

/** dist/<version>/: one folder per release, the earlier ones stay. */
function releaseDir(version = appVersions().version) {
  const dir = path.join(distDir, version);
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

/** Reads keys/keystore.properties and checks that the keystore exists, so that a long build does not fail at the end. */
function loadKeys() {
  if (!fs.existsSync(propsFile)) throw new Error(`Missing ${path.relative(root, propsFile)} (see README, Release APK)`);
  const props = Object.fromEntries(
    fs
      .readFileSync(propsFile, 'utf8')
      .split(/\r?\n/)
      .filter((l) => l && !l.startsWith('#') && l.includes('='))
      .map((l) => [l.slice(0, l.indexOf('=')).trim(), l.slice(l.indexOf('=') + 1).trim()]),
  );
  for (const k of ['storeFile', 'keyAlias', 'storePassword', 'keyPassword']) {
    if (!props[k]) throw new Error(`${k} missing in ${path.relative(root, propsFile)}`);
  }
  const storeFile = path.join(keysDir, props.storeFile);
  if (!fs.existsSync(storeFile)) throw new Error(`Missing keystore ${path.relative(root, storeFile)}`);
  return { ...props, storeFile };
}

function buildTools() {
  const sdk = process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT || path.join(process.env.LOCALAPPDATA || '', 'Android', 'Sdk');
  const dir = path.join(sdk, 'build-tools');
  if (!fs.existsSync(dir)) throw new Error(`Android SDK build-tools not found in ${dir}: set ANDROID_HOME`);
  const versions = fs.readdirSync(dir).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  const bt = path.join(dir, versions.pop());
  const win = process.platform === 'win32';
  return {
    zipalign: path.join(bt, win ? 'zipalign.exe' : 'zipalign'),
    apksigner: path.join(bt, win ? 'apksigner.bat' : 'apksigner'),
  };
}

/** Signs all the APKs of the Gradle release build into dist/<version>/ and returns their paths. */
function signAll(keys = loadKeys()) {
  const tools = buildTools();
  const { version } = appVersions();
  const inputs = fs.existsSync(apkDir) ? fs.readdirSync(apkDir).filter((f) => /^app-.*release\.apk$/.test(f)) : [];
  if (!inputs.length) throw new Error(`No APK in ${path.relative(root, apkDir)}: run assembleRelease first`);

  // APKs of an earlier build of this version (e.g. without splits) would end up in the checksums and the upload.
  const outDir = releaseDir(version);
  for (const f of fs.readdirSync(outDir)) {
    if (f.endsWith('.apk') || f.endsWith('.idsig') || f === 'SHA256SUMS.txt') fs.rmSync(path.join(outDir, f));
  }
  const env = { ...process.env, TB_STORE_PASS: keys.storePassword, TB_KEY_PASS: keys.keyPassword };
  const outputs = [];
  for (const input of inputs.sort()) {
    // app-release.apk, app-arm64-v8a-release.apk, app-universal-release.apk
    const variant = input.match(/^app-(.+)-release\.apk$/)?.[1];
    const output = path.join(outDir, `tinkerblink-${version}${variant ? `-${variant}` : ''}.apk`);
    const aligned = path.join(outDir, 'aligned.tmp.apk');
    execFileSync(tools.zipalign, ['-f', '-p', '4', path.join(apkDir, input), aligned], { stdio: 'inherit' });
    exec(
      tools.apksigner,
      [
        'sign',
        '--ks', keys.storeFile,
        '--ks-key-alias', keys.keyAlias,
        '--ks-pass', 'env:TB_STORE_PASS',
        '--key-pass', 'env:TB_KEY_PASS',
        '--out', output,
        aligned,
      ],
      { stdio: 'inherit', env },
    );
    fs.rmSync(aligned);
    fs.rmSync(`${output}.idsig`, { force: true });
    exec(tools.apksigner, ['verify', output], { stdio: 'inherit' });
    outputs.push(output);
  }

  const sums = outputs.map((f) => `${crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex')}  ${path.basename(f)}`);
  fs.writeFileSync(path.join(outDir, 'SHA256SUMS.txt'), `${sums.join('\n')}\n`);
  exec(tools.apksigner, ['verify', '--print-certs', outputs[0]], { stdio: 'inherit' });
  for (const f of outputs) console.log(`Signed APK: ${path.relative(root, f)} (${(fs.statSync(f).size / 1e6).toFixed(1)} MB)`);
  return outputs;
}

module.exports = { exec, loadKeys, signAll, appVersions, releaseDir, apkDir, root };

if (require.main === module) {
  try {
    signAll();
  } catch (e) {
    console.error(e instanceof Error ? e.message : e);
    process.exit(1);
  }
}
